import React from 'react';
import { useNavigate } from 'react-router-dom';
import Banner from '../components/Banner';
import TopRanking from '../components/TopRanking';
import './Home.css';

function Home() {
  const navigate = useNavigate();

  const notices = [
    {
      id: 1,
      title: '⚠️ LƯU Ý KHI ĐẶT ĐƠN TRÊN SHOP',
      items: [
        '- Đặt Đơn: Trang thái "Đã Giao" là dang "Dạng xử lý" => dạng cây tuyệt đối ko được về acc. Khi nào trang thái "Hoàn thành" là xong',
        '- Để xem TRẠNG THÁI đơn vui lòng NHẬP TÀY VÀO đơn đã đặt',
        '- Vào Acc trong lúc Đơn Trạng thái "Đã Giao" hoặc "Dạng xử lí" sẽ bị HỦY ĐƠN',
        '- Đơn sẽ mất từ 1-2 ngày để CẬP XONG nếu đơn bị sẽ lâu hơn nếu đơn TỐ',
        '- Có thể Đặt nhiều đơn ( số lít hơn nếu bạn ghi tên acc vào phần ghi chú ) | Đơn nào Thuê Trước Thì Cây Trước',
        '- Acc Bị 2 step Vui Lòng hộp cho Vô Chi Công để lấy video Hướng dẫn BẤT CHI CÔNG( mất bộ rồi thời )',
        '- Đơn gamepass có thể KHÔNG GHI MK những phải ghi tên TRONG GAME'
      ]
    }
  ];

  return (
    <div className="home">
      <Banner />
      <TopRanking />

      <div className="notices-section">
        <h2 className="section-title">⚠️ LƯU Ý QUAN TRỌNG</h2>
        {notices.map(notice => (
          <div key={notice.id} className="notice-card">
            <h3>{notice.title}</h3>
            <ul className="notice-items">
              {notice.items.map((item, idx) => (
                <li key={idx}>{item}</li>
              ))}
            </ul>
          </div>
        ))}
      </div>

      <div className="info-section">
        <div className="info-grid">
          <div className="info-card">
            <h3>📱 LIÊN HỆ VỚI CHÚNG TÔI</h3>
            <p><strong>TikTok:</strong> @congmix1zk7</p>
            <p><strong>YouTube:</strong> @vochicong2k7</p>
            <p><strong>Discord:</strong> vochicong2k7</p>
            <p><strong>Zalo:</strong> xxx-xxx-xxxx</p>
          </div>

          <div className="info-card">
            <h3>🎁 ƯU ĐÃI ĐẶC BIỆT</h3>
            <p>✅ Giá Rẻ Nhất Thị Trường</p>
            <p>✅ Giao Hàng Nhanh 1-2 Ngày</p>
            <p>✅ Hỗ Trợ 24/7</p>
            <p>✅ Hoàn Tiền 100% Nếu Lỗi</p>
          </div>

          <div className="info-card">
            <h3>🔒 AN TOÀN VÀ BẢO MẬT</h3>
            <p>✅ Mã Hóa SSL Toàn Bộ</p>
            <p>✅ Không Lưu Trữ Thông Tin</p>
            <p>✅ Xác Minh 2 Lớp</p>
            <p>✅ Chứng Chỉ Bảo Mật Quốc Tế</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Home;
